//! Required independent fixtures generated by the exact pinned Go implementation.
use super::{aead::{AuthIdGenerator, authid::crc32_ieee, kdf::kdf}, encoding::{BodyDecoder, BodyEncoder, BodySecurity, Direction, RequestHeader, ResponseHeader, VmessStream, command_key, response_key_iv, seal_request_payload}, validator::MemoryValidator};
use crate::common::{net::{Address, BoxStream, Destination}, protocol::{RequestCommand, SessionContext, User}};
use crate::features::{inbound::InboundHandler, outbound::OutboundHandler};
use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::{io, pin::Pin, sync::{Arc, Mutex}, task::{Context, Poll}, time::Duration};
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt, ReadBuf};
use uuid::Uuid;

#[derive(Deserialize)]
struct Vectors {
    commit: String, user_id: Uuid, timestamp: u64, cmd_key: String,
    auth_random: String, auth_id: String, connection_nonce: String,
    header_plain: String, request_wire: String, request_key: String,
    request_iv: String, response_header_byte: u8, response_key: String,
    response_iv: String, response_wire: String, kdf_auth: String,
    kdf_header: String, shake_masks: Vec<u16>, bodies: Vec<BodyVector>,
}
#[derive(Deserialize)]
struct BodyVector {security: u8, options: u8, command: u8, payload: String, request_wire: String, response_wire: String}
fn vectors() -> Vectors {
    // include_str is intentional: missing fixtures are a compile error, never a
    // successful zero-test run or an ignored/optional cross-language check.
    let json = include_str!("testdata/go-vectors.json");
    assert_eq!(hex::encode(Sha256::digest(json.as_bytes())), "25315d8abb22636487b7fea89971b78d1ffe824e8c2abab7daaeca48e92e6f4c", "verified independent fixture changed");
    let data: Vectors=serde_json::from_str(json).expect("required pinned-Go VMess fixtures");
    assert_eq!(data.commit,"67756b3674d56b72c7a7e675e8dcd3f883e1b2f7");
    assert_eq!(data.bodies.len(),24,"fixture coverage changed");
    for security in [3,4] {
        for options in [1,5,13,17,21,29] {
            for command in [1,2] {
                assert_eq!(data.bodies.iter().filter(|body| body.security==security && body.options==options && body.command==command).count(),1,"missing or duplicated fixture combination");
            }
        }
    }
    assert_eq!(data.shake_masks.len(),12);
    data
}
fn bytes(value: &str) -> Vec<u8> {hex::decode(value).expect("fixture hex")}
fn fixed<const N:usize>(value: &str) -> [u8;N] {bytes(value).try_into().expect("fixture array length")}
fn request(data: &Vectors) -> RequestHeader {
    let mut header=RequestHeader::decode_payload(data.user_id,&bytes(&data.header_plain)).unwrap();
    assert_eq!(header.request_body_key,fixed::<16>(&data.request_key));
    assert_eq!(header.request_body_iv,fixed::<16>(&data.request_iv));
    assert_eq!(header.response_header_byte,data.response_header_byte);
    header.security=BodySecurity::Aes128Gcm;header
}
fn validator(id: Uuid) -> MemoryValidator {let validator=MemoryValidator::new();validator.add(User::new(id)).unwrap();validator}

#[test]
fn pinned_go_kdf_authid_shake_request_and_response_bytes() {
    let data=vectors();let request=request(&data);let key=command_key(&data.user_id);
    assert_eq!(hex::encode(key),data.cmd_key);
    assert_eq!(crc32_ieee(b"123456789"),0xcbf4_3926);
    let auth=AuthIdGenerator::new(&key);
    let id=auth.create_with_random(data.timestamp,fixed(&data.auth_random));
    assert_eq!(hex::encode(id),data.auth_id);
    assert_eq!(hex::encode(kdf(&key,&[b"AES Auth ID Encryption"])),data.kdf_auth);
    let nonce=fixed::<8>(&data.connection_nonce);
    assert_eq!(hex::encode(kdf(&key,&[b"VMess Header AEAD Key",&id,&nonce])),data.kdf_header);
    assert_eq!(request.encode_payload(&[]).unwrap(),bytes(&data.header_plain));
    assert_eq!(seal_request_payload(&key,&bytes(&data.header_plain),&id,&nonce).unwrap(),bytes(&data.request_wire));
    let mut shake=super::encoding::auth::ShakeSizeParser::new(&request.request_body_iv);
    assert_eq!((0..12).map(|_|shake.next_mask()).collect::<Vec<_>>(),data.shake_masks);
    let (response_key,response_iv)=response_key_iv(&request);
    assert_eq!(hex::encode(response_key),data.response_key);
    assert_eq!(hex::encode(response_iv),data.response_iv);
    let response=bytes(&data.response_wire);
    assert_eq!(ResponseHeader::new(request.response_header_byte).encode_bytes(&request).unwrap(),response);
    assert_eq!(ResponseHeader::decode_length(&request,&response[..18]).unwrap(),4);
    assert_eq!(ResponseHeader::decode_payload(&request,&response[18..]).unwrap().response_header_byte,request.response_header_byte);
}

#[tokio::test]
async fn pinned_go_all_body_security_options_and_directions() {
    let data=vectors();
    for case in &data.bodies {
        let mut request=request(&data);request.security=BodySecurity::from_byte(case.security).unwrap();
        request.options=case.options;request.command=RequestCommand::from_u8(case.command).unwrap();
        for (direction,wire) in [(Direction::Request,&case.request_wire),(Direction::Response,&case.response_wire)] {
            let expected=bytes(wire);let plain=bytes(&case.payload);
            let mut encoder=BodyEncoder::new(&request,direction).unwrap();
            let mut random=0u8;
            let mut fill=|padding: &mut [u8]| {for byte in padding {*byte=random;random=random.wrapping_add(1);}};
            let mut encoded=encoder.encode_frame_with_padding(&plain,&mut fill).unwrap();
            encoded.extend(encoder.encode_frame_with_padding(&[],&mut fill).unwrap());
            assert_eq!(encoded,expected,"encode security={} options={} command={} {direction:?}",case.security,case.options,case.command);
            let mut reader=Fragmented::new(std::io::Cursor::new(expected),1);
            let mut decoder=BodyDecoder::new(&request,direction).unwrap();
            assert_eq!(decoder.read_frame(&mut reader).await.unwrap(),plain,"Go decode {direction:?}");
            assert!(decoder.read_frame(&mut reader).await.unwrap().is_empty());
        }
    }
}

#[tokio::test]
async fn pinned_go_runtime_reads_every_cipher_option_and_packet_combination() {
    let data = vectors();
    for case in &data.bodies {
        let mut request = request(&data);
        request.security = BodySecurity::from_byte(case.security).unwrap();
        request.options = case.options;
        request.command = RequestCommand::from_u8(case.command).unwrap();
        let mut response = bytes(&data.response_wire);
        response.extend(bytes(&case.response_wire));
        let (inner, _) = memory(response, 1);
        let mut client = VmessStream::client(inner, request.clone()).unwrap();
        let mut plain = Vec::new(); client.read_to_end(&mut plain).await.unwrap();
        assert_eq!(plain, bytes(&case.payload), "runtime Go response: {} / {} / {}", case.security, case.options, case.command);
        let (inner, _) = memory(bytes(&case.request_wire), 1);
        let mut server = VmessStream::server(inner, request).unwrap();
        plain.clear(); server.read_to_end(&mut plain).await.unwrap();
        assert_eq!(plain, bytes(&case.payload), "runtime Go request: {} / {} / {}", case.security, case.options, case.command);
    }
}

#[test]
fn replay_registration_is_atomic_across_parallel_connections() {
    let data = vectors();
    let validator = Arc::new(validator(data.user_id));
    let barrier = Arc::new(std::sync::Barrier::new(16));
    let id = fixed::<16>(&data.auth_id);
    let now = data.timestamp;
    let threads = (0..16).map(|_| {
        let validator = validator.clone(); let barrier = barrier.clone();
        std::thread::spawn(move || { barrier.wait(); validator.authenticate(&id, now).is_ok() })
    }).collect::<Vec<_>>();
    assert_eq!(threads.into_iter().map(|thread| usize::from(thread.join().unwrap())).sum::<usize>(), 1);
    let barrier = Arc::new(std::sync::Barrier::new(16));
    let request = request(&data);
    let threads = (0..16).map(|_| {
        let validator = validator.clone(); let barrier = barrier.clone(); let request = request.clone();
        std::thread::spawn(move || { barrier.wait(); validator.register_session(&request, now).is_ok() })
    }).collect::<Vec<_>>();
    assert_eq!(threads.into_iter().map(|thread| usize::from(thread.join().unwrap())).sum::<usize>(), 1);
    assert!(validator.register_session(&request, now + 179).is_err());
    assert!(validator.register_session(&request, now + 180).is_ok());
}

#[tokio::test]
async fn pinned_go_fragmented_request_and_replay_rejection() {
    let data=vectors();let validator=validator(data.user_id);let wire=bytes(&data.request_wire);
    let decoded=RequestHeader::decode_at(&mut Fragmented::new(std::io::Cursor::new(wire.clone()),1),&validator,data.timestamp).await.unwrap();
    assert_eq!(decoded.destination,Destination::tcp(Address::Domain("example.org".into()),443));
    assert_eq!(decoded.options,13);
    assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(wire),&validator,data.timestamp).await.is_err(),"AuthID replay accepted");
    let key=command_key(&data.user_id);
    let fresh=AuthIdGenerator::new(&key).create_with_random(data.timestamp,[9,8,7,6]);
    let same_session=seal_request_payload(&key,&bytes(&data.header_plain),&fresh,&[0;8]).unwrap();
    let error=RequestHeader::decode_at(&mut std::io::Cursor::new(same_session),&validator,data.timestamp).await.unwrap_err();
    assert!(error.to_string().contains("body key/IV"),"{error}");
}

#[tokio::test]
async fn pinned_go_timestamp_boundaries_wrong_users_and_plaintext_deny() {
    let data=vectors();let wire=bytes(&data.request_wire);
    for now in [data.timestamp-120,data.timestamp+120] {
        assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(wire.clone()),&validator(data.user_id),now).await.is_ok());
    }
    for now in [data.timestamp-121,data.timestamp+121] {
        assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(wire.clone()),&validator(data.user_id),now).await.is_err());
    }
    assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(wire.clone()),&MemoryValidator::new(),data.timestamp).await.is_err());
    assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(wire),&validator(Uuid::nil()),data.timestamp).await.is_err());
    let mut old_plaintext=data.user_id.as_bytes().to_vec();old_plaintext.extend(bytes(&data.header_plain));
    assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(old_plaintext),&validator(data.user_id),data.timestamp).await.is_err());
    let auth=AuthIdGenerator::new(&command_key(&data.user_id));
    assert!(!auth.matches(&auth.create_with_random(u64::MAX,[0;4]),data.timestamp,120));
}

#[tokio::test]
async fn pinned_go_corrupt_and_truncated_request_headers_fail_closed() {
    let data=vectors();let wire=bytes(&data.request_wire);
    for offset in [0,15,16,33,34,41,42,wire.len()-1] {
        let mut corrupt=wire.clone();corrupt[offset]^=0x80;
        assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(corrupt),&validator(data.user_id),data.timestamp).await.is_err(),"tamper offset {offset}");
    }
    for length in 0..wire.len() {
        assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(wire[..length].to_vec()),&validator(data.user_id),data.timestamp).await.is_err(),"truncation {length}");
    }
    let mut payload=bytes(&data.header_plain);let last=payload.len()-1;payload[last]^=1;
    let bad_checksum=seal_request_payload(&command_key(&data.user_id),&payload,&fixed(&data.auth_id),&fixed(&data.connection_nonce)).unwrap();
    assert!(RequestHeader::decode_at(&mut std::io::Cursor::new(bad_checksum),&validator(data.user_id),data.timestamp).await.is_err());
}

#[tokio::test]
async fn pinned_go_response_auth_and_body_auth_are_mandatory() {
    let data=vectors();let request=request(&data);let wire=bytes(&data.response_wire);
    for offset in [0,17,18,wire.len()-1] {
        let mut corrupt=wire.clone();corrupt[offset]^=1;
        assert!(ResponseHeader::decode(&mut std::io::Cursor::new(corrupt),&request).await.is_err());
    }
    let mut wrong=request.clone();wrong.response_header_byte^=1;
    assert!(ResponseHeader::decode(&mut std::io::Cursor::new(wire.clone()),&wrong).await.is_err());
    wrong=request.clone();wrong.request_body_key[0]^=1;
    assert!(ResponseHeader::decode(&mut std::io::Cursor::new(wire),&wrong).await.is_err());
    for case in &data.bodies {
        let mut request=request.clone();request.security=BodySecurity::from_byte(case.security).unwrap();request.options=case.options;
        for (direction,wire) in [(Direction::Request,&case.request_wire),(Direction::Response,&case.response_wire)] {
            let original=bytes(wire);let decoder=BodyDecoder::new(&request,direction).unwrap();let length_size=decoder.length_bytes();
            let mut corrupt=original.clone();corrupt[length_size+7]^=1;
            assert!(BodyDecoder::new(&request,direction).unwrap().read_frame(&mut std::io::Cursor::new(corrupt)).await.is_err());
            if case.options&16!=0 {
                let mut corrupt=original.clone();corrupt[0]^=1;
                assert!(BodyDecoder::new(&request,direction).unwrap().read_frame(&mut std::io::Cursor::new(corrupt)).await.is_err());
            }
            let mut bad_key=request.clone();bad_key.request_body_key[0]^=0x80;
            assert!(BodyDecoder::new(&bad_key,direction).unwrap().read_frame(&mut std::io::Cursor::new(original)).await.is_err());
        }
    }
}

#[tokio::test]
async fn pinned_go_stream_runtime_consumes_response_and_emits_authenticated_body() {
    let data=vectors();
    for security in [3,4] {
        let case=data.bodies.iter().find(|case|case.security==security&&case.options==1&&case.command==1).unwrap();
        let mut request=request(&data);request.security=BodySecurity::from_byte(security).unwrap();request.options=1;
        let mut input=bytes(&data.response_wire);input.extend(bytes(&case.response_wire));
        let (inner,output)=memory(input,1);
        let mut client=VmessStream::client(inner,request.clone()).unwrap();
        let mut plain=Vec::new();client.read_to_end(&mut plain).await.unwrap();assert_eq!(plain,bytes(&case.payload));
        client.write_all(&plain).await.unwrap();client.shutdown().await.unwrap();
        assert_eq!(*output.lock().unwrap(),bytes(&case.request_wire));
        let (inner,output)=memory(bytes(&case.request_wire),2);
        let mut server=VmessStream::server(inner,request).unwrap();
        plain.clear();server.read_to_end(&mut plain).await.unwrap();assert_eq!(plain,bytes(&case.payload));
        server.write_all(&plain).await.unwrap();server.shutdown().await.unwrap();
        let mut expected=bytes(&data.response_wire);expected.extend(bytes(&case.response_wire));
        assert_eq!(*output.lock().unwrap(),expected);
    }
}

#[tokio::test]
async fn invalid_stream_never_falls_back_and_truncation_is_detected() {
    let data=vectors();let request=request(&data);
    let case=data.bodies.iter().find(|case|case.security==3&&case.options==13&&case.command==1).unwrap();
    let wire=bytes(&case.request_wire);
    for length in [1,2,3,20,260] {
        let (inner,_)=memory(wire[..length].to_vec(),1);
        let mut stream=VmessStream::server(inner,request.clone()).unwrap();
        assert!(stream.read_to_end(&mut Vec::new()).await.is_err(),"truncated stream accepted at {length}");
        assert!(stream.read(&mut [0u8;1]).await.is_err(),"reader resumed after auth/truncation error");
    }
    let mut invalid=wire;invalid[5]^=1;
    let (inner,_)=memory(invalid,1);let mut stream=VmessStream::server(inner,request).unwrap();
    assert!(stream.read(&mut [0u8;512]).await.is_err());assert!(stream.read(&mut [0u8;512]).await.is_err());
}

#[tokio::test]
async fn runtime_tcp_inbound_outbound_fragmented_loopback_and_half_close() {
    tokio::time::timeout(Duration::from_secs(15),async {
        for security in ["aes-128-gcm","chacha20-poly1305"] {
            for signal in [true,false] {
                let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let addr=listener.local_addr().unwrap();
                let id=Uuid::from_bytes([0x41;16]);let target=Destination::tcp(Address::Domain("example.org".into()),443);
                let payload=(0..8193).map(|i|(i%251)as u8).collect::<Vec<_>>();let expected=payload.clone();let expected_target=target.clone();
                let server=tokio::spawn(async move {
                    let (socket,remote)=listener.accept().await.unwrap();
                    let server=super::inbound::Server::new("vmess-test",vec![id]);
                    let mut inbound=server.handle_connection(Box::pin(Fragmented::new(socket,3)),remote).await.unwrap();
                    assert_eq!(inbound.session.destination,expected_target);assert_eq!(inbound.session.user.unwrap().id,id);
                    let mut incoming=Vec::new();inbound.stream.read_to_end(&mut incoming).await.unwrap();assert_eq!(incoming,expected);
                    inbound.stream.write_all(&incoming).await.unwrap();inbound.stream.shutdown().await.unwrap();
                });
                let client=super::outbound::Client::new("vmess-client",Destination::tcp(Address::Ipv4(std::net::Ipv4Addr::LOCALHOST),addr.port()),id,None,None)
                    .with_security(security).unwrap().with_termination_signal(signal);
                let mut stream=client.connect(&SessionContext::new("test",target)).await.unwrap();
                stream.write_all(&payload).await.unwrap();stream.shutdown().await.unwrap();
                let mut echo=Vec::new();stream.read_to_end(&mut echo).await.unwrap();assert_eq!(echo,payload);server.await.unwrap();
            }
        }
    }).await.expect("VMess TCP loopback deadlock");
}

#[tokio::test]
async fn runtime_udp_datagrams_remain_separate_under_fragmentation() {
    tokio::time::timeout(Duration::from_secs(10),async {
        let data=vectors();
        for security in [BodySecurity::Aes128Gcm,BodySecurity::ChaCha20Poly1305] {
            let mut request=request(&data);request.security=security;request.command=RequestCommand::Udp;
            let (left,right)=tokio::io::duplex(32);
            let mut client=VmessStream::client(Box::pin(Fragmented::new(left,3)),request.clone()).unwrap();
            let mut server=VmessStream::server(Box::pin(Fragmented::new(right,2)),request).unwrap();
            let first=vec![0x31;257];let second=vec![0x72;517];let a=first.clone();let b=second.clone();
            let task=tokio::spawn(async move {
                assert_eq!(server.recv_packet().await.unwrap(),Some(a.clone()));assert_eq!(server.recv_packet().await.unwrap(),Some(b.clone()));
                server.send_packet(&a).await.unwrap();server.send_packet(&b).await.unwrap();server.shutdown().await.unwrap();
            });
            client.send_packet(&first).await.unwrap();client.send_packet(&second).await.unwrap();
            assert_eq!(client.recv_packet().await.unwrap(),Some(first));assert_eq!(client.recv_packet().await.unwrap(),Some(second));
            assert_eq!(client.recv_packet().await.unwrap(),None);
            // Go common/crypto/auth.go:167 returns EOF before the terminal tag
            // and padding. Drain them only after protocol EOF so duplex(32)
            // lets the peer finish shutdown rather than blocking on its tail.
            let mut transport=client.into_inner();
            let trailing=tokio::io::copy(&mut transport,&mut tokio::io::sink()).await.unwrap();
            assert_eq!(trailing,41,"protocol EOF must leave the terminal tag (16) and fixture padding (25) unread");
            task.await.unwrap();
        }
    }).await.expect("VMess UDP loopback deadlock");
}

#[test]
fn invalid_security_options_addresses_and_oversized_packets_are_rejected() {
    let data=vectors();let mut header=request(&data);
    for mode in ["none","zero","aes-128-cfb","unknown"] {assert!(BodySecurity::from_name(mode).is_err());}
    for mode in [0,1,2,5,6,15] {assert!(BodySecurity::from_byte(mode).is_err());}
    header.options=9;assert!(BodyEncoder::new(&header,Direction::Request).is_err());
    header=request(&data);header.destination=Destination::tcp(Address::Domain("a".repeat(256)),443);assert!(header.encode_payload(&[]).is_err());
    header.destination=Destination::tcp(Address::Domain(String::new()),443);assert!(header.encode_payload(&[]).is_err());
    header=request(&data);header.command=RequestCommand::Udp;
    assert!(BodyEncoder::new(&header,Direction::Request).unwrap().encode_frame(&vec![0;8192]).is_err());
    let mut encoder=BodyEncoder::new(&header,Direction::Request).unwrap();encoder.encode_frame(&[]).unwrap();assert!(encoder.encode_frame(b"after end").is_err());
}

#[test]
fn mux_header_has_no_address_and_uses_reserved_destination() {
    let data=vectors();let mut header=request(&data);header.command=RequestCommand::Mux;
    let payload=header.encode_payload(&[1,2,3,4]).unwrap();assert_eq!(payload.len(),38+4+4);
    let decoded=RequestHeader::decode_payload(data.user_id,&payload).unwrap();assert_eq!(decoded.command,RequestCommand::Mux);
    assert_eq!(decoded.destination,Destination::tcp(Address::Domain("v1.mux.cool".into()),0));
}

/// Force every second poll to Pending and limit both transport directions.
struct Fragmented<T> {inner:T,limit:usize,read_pending:bool,write_pending:bool}
impl<T> Fragmented<T> {fn new(inner:T,limit:usize)->Self {Self {inner,limit,read_pending:true,write_pending:true}}}
impl<T:AsyncRead+Unpin> AsyncRead for Fragmented<T> {
    fn poll_read(self:Pin<&mut Self>,cx:&mut Context<'_>,buf:&mut ReadBuf<'_>)->Poll<io::Result<()>> {
        let this=self.get_mut();if buf.remaining()==0{return Poll::Ready(Ok(()));}
        if this.read_pending {this.read_pending=false;cx.waker().wake_by_ref();return Poll::Pending;}
        this.read_pending=true;let mut scratch=[0u8;256];let size=buf.remaining().min(this.limit).min(scratch.len());
        let mut incoming=ReadBuf::new(&mut scratch[..size]);
        match Pin::new(&mut this.inner).poll_read(cx,&mut incoming) {
            Poll::Ready(Ok(()))=>{buf.put_slice(incoming.filled());Poll::Ready(Ok(()))},other=>other,
        }
    }
}
impl<T:AsyncWrite+Unpin> AsyncWrite for Fragmented<T> {
    fn poll_write(self:Pin<&mut Self>,cx:&mut Context<'_>,bytes:&[u8])->Poll<io::Result<usize>> {
        let this=self.get_mut();
        if this.write_pending {this.write_pending=false;cx.waker().wake_by_ref();return Poll::Pending;}
        this.write_pending=true;Pin::new(&mut this.inner).poll_write(cx,&bytes[..bytes.len().min(this.limit)])
    }
    fn poll_flush(self:Pin<&mut Self>,cx:&mut Context<'_>)->Poll<io::Result<()>> {Pin::new(&mut self.get_mut().inner).poll_flush(cx)}
    fn poll_shutdown(self:Pin<&mut Self>,cx:&mut Context<'_>)->Poll<io::Result<()>> {Pin::new(&mut self.get_mut().inner).poll_shutdown(cx)}
}
struct MemoryIo {input:Vec<u8>,position:usize,output:Arc<Mutex<Vec<u8>>>}
fn memory(input:Vec<u8>,limit:usize)->(BoxStream,Arc<Mutex<Vec<u8>>>) {
    let output=Arc::new(Mutex::new(Vec::new()));
    (Box::pin(Fragmented::new(MemoryIo {input,position:0,output:output.clone()},limit)),output)
}
impl AsyncRead for MemoryIo {
    fn poll_read(self:Pin<&mut Self>,_:&mut Context<'_>,buf:&mut ReadBuf<'_>)->Poll<io::Result<()>> {
        let this=self.get_mut();let size=buf.remaining().min(this.input.len()-this.position);
        buf.put_slice(&this.input[this.position..this.position+size]);this.position+=size;Poll::Ready(Ok(()))
    }
}
impl AsyncWrite for MemoryIo {
    fn poll_write(self:Pin<&mut Self>,_:&mut Context<'_>,bytes:&[u8])->Poll<io::Result<usize>> {self.output.lock().unwrap().extend_from_slice(bytes);Poll::Ready(Ok(bytes.len()))}
    fn poll_flush(self:Pin<&mut Self>,_:&mut Context<'_>)->Poll<io::Result<()>> {Poll::Ready(Ok(()))}
    fn poll_shutdown(self:Pin<&mut Self>,_:&mut Context<'_>)->Poll<io::Result<()>> {Poll::Ready(Ok(()))}
}
